        clauses.append(clause)

        clause = [-var, variables[2 * i - 1]]
        clauses.append(clause)

    for i in range(1, n + 1):
        var = variables[2 * i - 2]
        clause = [variables[2 * i - 1]]
        for j in range(1, n + 1):
            if i != j:
                clause.append(-variables[2 * j - 2])
        clauses.append(clause)

    return clauses

def matrix_factorization(clauses):
    n = len(clauses)
    A = [[0] * (n + 1) for _ in range(n + 1)]

    for i, clause in enumerate(clauses):
        for var in clause:
            if var > 0:
                A[i][var - 1] += 1
            else:
                A[i][-var - 1] -= 1

    # Gaussian elimination to find the matrix factorization
    for i in range(n + 1):
        if A[i][i] == 0:
            return None, None

        for j in range(i + 1, n + 1):
            factor = Fraction(A[j][i], A[i][i])
            for k in range(n + 1):
                A[j][k] -= factor * A[i][k]

    # Extract the matrix factorization
    U = [[0] * (n + 1) for _ in range(n + 1)]
    V = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(n):
            if i == j:
                U[i][j] = A[i][i]
                V[j][i] = Fraction(1, A[i][i])
            else:
                U[i][j] = A[i][j + 1]
                V[j][i] = -A[j][i + 1] * Fraction(1, A[i][i])

    return U, V

def resolution_tree_width(clauses):
    n = len(clauses)
    tree = {}

    for i in range(n):
        tree[i] = set()

    for clause in clauses:
        if len(clause) == 2:
